package com.example.dsatracker.model;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;import java.util.HashSet;import java.util.Set;@Entity@Table(        name = "problems",        uniqueConstraints = {                @UniqueConstraint(columnNames = "leetcodeId")        })@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class Problem {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false, unique = true)    private Integer leetcodeId;    @Column(nullable = false, length = 200)    private String title;    @Enumerated(EnumType.STRING)    @Column(nullable = false)    private Difficulty difficulty;    @Column(nullable = false, length = 500)    private String url;    @Column(nullable = false, updatable = false)    private LocalDateTime createdAt;    @ManyToMany(fetch = FetchType.LAZY)    @JoinTable(            name = "problem_tags",            joinColumns = @JoinColumn(name = "problem_id"),            inverseJoinColumns = @JoinColumn(name = "tag_id")    )    @Builder.Default    private Set<Tag> tags = new HashSet<>();    @PrePersist    public void onCreate() {        createdAt = LocalDateTime.now();    }}